import json
A=Path('app/src/main/assets')
def f(id,label,good,trap,legend):return dict(id=id,label=label,title=label,good=good,trap=trap,legend=legend)
P=dict(title='Солидные образования поджелудочной и имитаторы',localLabel='Паттерны',spreadLabel='Протоки и сосуды')
P['local']=[
f('ps-pdac','Аденокарцинома · PDAC','Часто нечёткий T1-гипоинтенсивный гиповаскулярный очаг, обрыв главного панкреатического протока (ГПП), расширение выше и дистальная атрофия. При опухоли головки возможен double-duct sign.','Малый рак бывает почти изоинтенсивным: вторичные протоковые признаки важны даже без видимой массы. T2-сигнал и DWI вариабельны; гиповаскулярность не доказывает PDAC.',['Гиповаскулярный очаг головки','Обрыв и расширение ГПП к телу/хвосту','Расширенный желчный проток']),
f('ps-net','Нейроэндокринная опухоль · Pan-NET','Небольшая чёткая артериально гиперваскулярная масса часто соответствует Pan-NET. Оцените T2, DWI/ADC, некроз, проток, сосуды и печень во всех фазах.','Pan-NET может быть гиповаскулярной, крупной или кистозной. По усилению нельзя определить Ki-67, NET G1–G3, NEC или гормональную активность; нужна клиника и морфология.',['Артериально гиперваскулярный очаг','ГПП: проверьте компрессию/дилатацию','Печень — поиск гиперваскулярных метастазов']),
f('ps-focal','Очаговый панкреатит','Воспалительная масса может усиливаться отсроченно; проходящий через неё видимый проток без резкого обрыва (duct-penetrating sign) поддерживает воспалительную природу. Кальцинаты лучше оценивает КТ.','Признак не абсолютен. Новый очаг на фоне хронического панкреатита может быть раком; отсутствие опухолевых клеток в одной биопсии не гарантирует исключения рака.',['Воспалительное увеличение','ГПП прослеживается через массу','Окружающие воспалительные изменения']),
f('ps-aip','Аутоиммунный панкреатит','Диффузное «колбасовидное» увеличение, сглаженность дольчатости, капсулоподобный ободок, отсроченное усиление и длинное/множественное сужение ГПП поддерживают AIP. Бывает и очаговая форма.','МРТ не заменяет ICDC: учитывают паренхиму/проток, серологию, другие органы, гистологию и в отдельных условиях ответ на лечение. Пробное лечение стероидами нельзя назначать по одной МРТ до исключения рака.',['Диффузно увеличенная железа','Капсулоподобный ободок','Длинный суженный участок ГПП']),
f('ps-spn','Солидно-псевдопапиллярная опухоль','Обычно инкапсулированная масса с солидной тканью и геморрагическими/кистозными участками; часто у молодых женщин. T1-яркие участки проверяют на доконтрастной серии.','Возраст и пол не устанавливают диагноз. Некротические Pan-NET, ацинарная опухоль и другие массы могут выглядеть сходно; крупный размер сам по себе не определяет гистологию.',['Капсула образования','Солидная усиливающаяся ткань','Кровоизлияние / кистозная часть']),
f('ps-spleen','Добавочная селезёнка и другие имитаторы','Очаг в хвосте, повторяющий селезёнку по T1/T2, DWI и характеру усиления во всех фазах, может быть внутрипанкреатической добавочной селезёнкой. Сравнение обязательно на одной серии.','Гиперваскулярность сама по себе недостаточна: возможны Pan-NET и метастазы, особенно RCC. При неуверенности обсуждают специфическое подтверждение селезёночной ткани; не объявляют NET по одному очагу.',['Узел в хвосте','Селезёнка для посерийного сравнения','Хвост поджелудочной'])]
P['spread']=[
f('ps-duct','Обрыв или проходящий проток','МРХПГ: точка перехода, длина сужения, калибр проксимальнее, боковые ветви и атрофия. Double-duct sign — сочетание билиарной и панкреатической обструкции.','Одновременное расширение двух протоков не равно раку. Воспалительная стриктура и ампулярная патология требуют сопоставления; отрицательная МРТ не исключает малый очаг.',['Точка обрыва ГПП','Расширение ГПП к хвосту','Желчный проток у головки']),
f('ps-angle','Контакт с сосудом · ≤180° / >180°','Оценивайте контакт по окружности сосуда в плоскости, перпендикулярной его оси: нет, ≤180° или >180°. Укажите конкретный сосуд, длину контакта, стеноз и деформацию.','180° относится к полной окружности сосуда, не к половине поджелудочной. Один угол не определяет резектабельность; воспаление и ткань после лечения могут имитировать контакт.',['Увеличенный поперечный срез сосуда','Дуга контакта с опухолью','Условная опухолевая ткань']),
f('ps-vein','Вены · стеноз · тромб','Для воротной/верхней брыжеечной вен: степень и длина сужения/окклюзии, контур, тромб, коллатерали и свободные сегменты выше/ниже для оценки реконструкции.','Угол ≤180° не исключает значимого венозного поражения при деформации. Неразличимая граница не доказывает инвазию; опухолевый тромб требует подтверждённой усиливающейся ткани.',['Участок контакта и деформации вены','Внутрипросветный компонент / тромб','Проходимые участки выше и ниже']),
f('ps-spread','Распространение и после лечения','Печень, брюшина/асцит, узлы, соседние органы, артериальные варианты. В описании артерий отдельно укажите SMA, чревный ствол и общую печёночную, а для тела/хвоста — селезёночные сосуды.','После неоадъювантного лечения сохраняющаяся периваскулярная ткань не равна жизнеспособной опухоли. Размер и контакт сопоставляют с исходной картиной, метастазами и решением команды.',['Первичная опухоль','Отдалённый очаг в печени','Периваскулярная ткань: морфология не равна жизнеспособности'])]
P['assessment']=[['Подозрительный солидный очаг','Локализация, 3 размера, края, T1/T2, DWI/ADC и усиление относительно железы. Ищите протоковые признаки даже без чёткой массы. Укажите диагностическую уверенность и дифференциальный ряд.'],['PDAC и воспаление','Резкий обрыв ГПП, атрофия выше обструкции, гиповаскулярный очаг и сосудистые изменения настораживают. Проходящий проток/отсроченное усиление поддерживают воспаление, но не исключают рак.'],['Pan-NET','Мультифазная оценка обязательна: гиперваскулярность не универсальна. МРТ не определяет grade, Ki-67 и гормональную активность; ЭУС/морфология и рецепторная визуализация дополняют стадирование по задаче.'],['AIP · рамка ICDC2011','Паренхиматозные и протоковые признаки + серология + другие органы + гистология; ответ на стероиды — дополнительный критерий в контролируемом клиническом маршруте. Здесь показаны МР-паттерны, не полный автодиагностический алгоритм ICDC.'],['Сосудистый контакт · SAR/APA2014','Нет контакта; ≤180°; >180°. Для каждого сосуда — угол, длина, контур, стеноз/окклюзия, ветви и варианты. Терминология шаблона2014 не является актуальным универсальным алгоритмом NCCN/резектабельности.'],['Венозная реконструкция','Воротная/верхняя брыжеечная вены: длина поражения, проходимые сегменты, конфлюенс, ветви, коллатерали. Операбельность определяют хирург и команда по полному исследованию, не только по углу.'],['Лимфоузлы / метастазы','Укажите станции и подозрительную морфологию; нормальный размер не исключает метастаз, увеличенный узел может быть реактивным. Абдоминальная МРТ не заменяет полное стадирование вне покрытия.'],['Если масса не найдена','При необъяснимом новом обрыве/расширении протока, дистальной атрофии или клиническом подозрении нужна дальнейшая оценка (ЭУС / специализированная КТ / повторное исследование по ситуации), а не уверенное исключение опухоли.']]
P['pitfalls']=[['Хронический панкреатит не защищает от рака','Сравните с предыдущими исследованиями: новый мягкотканный компонент, смещение кальцинатов, обрыв и нарастающая атрофия требуют уточнения.'],['IgG4 и AIP','Повышение IgG4 само по себе не исключает PDAC. Ищите билиарные стриктуры, почечные и другие IgG4-ассоциированные изменения; AIP типа2 может не сопровождаться IgG4-повышением.'],['Гиперваскулярная масса хвоста','Сравните со селезёнкой во всех фазах. Метастаз RCC, добавочная селезёнка и Pan-NET могут пересекаться по картине; анамнез и дополнительное подтверждение важны.'],['DWI и лечение','Рестрикция встречается при опухоли и воспалении. После лечения фиброз/отёк затрудняют измерение опухоли и контакта; нельзя автоматически объявлять неоперабельность по остаточной ткани.']]
P['scan']=[['Обязательно · покрытие','Вся железа, ГПП, желчные пути; печень и регионарные сосуды/узлы','Тонкие срезы через очаг; отдельная оценка артериальной и венозной анатомии.'],['Обязательно · T2','AX/COR T2 с/без FS + тонкая МРХПГ','Проток, обрыв/проходящий проток, отёк, капсула, жидкость. MIP проверять на исходных срезах.'],['Обязательно · T1','T1 FS до контраста, IP/OP или Dixon','Контраст опухоли на фоне железы, кровь/жир, исходная серия для субтракции.'],['Обязательно для характеризации','Тонкая 3D T1 FS динамика: ранняя артериальная, панкреатическая/поздняя артериальная, портальная; отсроченная по задаче','Ранний гиперваскулярный NET не должен теряться; гиповаскулярный PDAC и позднее усиление оценивают в сопоставимых фазах. Тайминг подстраивают по болюсу.'],['Обязательно · диффузия','DWI с картой ADC и несколькими b-факторами','Поиск малого очага и метастазов; не самостоятельный критерий гистологии. При печёночных очагах прицельная МРТ печени по задаче.'],['Дополнительно','Специализированная мультифазная КТ / ЭУС ± биопсия / рецепторная ПЭТ для NET по показаниям','Уточнение сосудов, кальцинатов, малого очага и морфологии. Недиагностические фазы и отсутствие контраста прямо ограничивают заключение.']]
P['checks']=['Очаг и вторичные признаки при невидимой массе','ГПП и холедох: калибр, уровень и длина перехода','Усиление по фазам, кровь/некроз, DWI/ADC','SMA, чревный ствол, печёночная артерия: угол/длина','Воротная/брыжеечная вены: деформация, окклюзия, тромб','Печень, брюшина, узлы, соседние органы, варианты сосудов','Анамнез панкреатита/лечения, сравнение и ограничения']
P['reports']=[['Подозрение на PDAC','В [отделе] нечёткая гиповаскулярная масса [ ] мм с [обрывом ГПП, расширением до ] и [атрофией]. Артерии [контакт по каждому], вены [ ]. Печень/брюшина/узлы в покрытии [ ]. Картина подозрительна на PDAC; требуется профильная верификация и стадирование.'],['Невидимая масса / проток','Определяются [обрыв/локальная стриктура] ГПП в [ ], расширение выше до [ ] мм и [атрофия]. Достоверная масса на доступных сериях не визуализирована. Малое солидное образование не исключено; требуется уточнение причины обструкции.'],['Гиперваскулярное образование','В [ ] солидный артериально гиперваскулярный очаг [ ] мм, ГПП [ ], сосуды [ ], печень [ ]. Возможна Pan-NET; дифференциально [ ]. Grade, гормональная активность и гистологический тип по МРТ не определяются.'],['Воспалительный паттерн','Фокальное увеличение [ ] с [проходящим ГПП/отсроченным усилением/воспалением]. Картина может соответствовать воспалительной массе, однако опухоль не исключена. Предыдущие исследования [ ], дальнейшее клиническое/ЭУС-уточнение по ситуации.'],['AIP-паттерн','[Диффузное/очаговое] увеличение железы с [ободком], отсроченным усилением и [длинным сужением ГПП]. Внепанкреатические изменения [ ]. Картина совместима с AIP в соответствующем контексте; для диагноза нужны другие компоненты критериев и исключение рака.'],['Сосуды / после лечения','По сравнению с [дата] после [лечение]: масса [ ], контакт с [сосудом] [≤180°/>180°] на длине [ ] мм, контур/просвет [ ], тромб [ ]. Метастатические изменения [ ]. Остаточная периваскулярная ткань по МРТ не позволяет уверенно разделить фиброз и жизнеспособную опухоль.']]
L=dict(title='Диффузные заболевания печени',localLabel='Паренхима',spreadLabel='Сосуды и осложнения')
L['local']=[
f('ld-fat','Диффузный стеатоз','Диффузное падение сигнала на opposed-phase относительно in-phase поддерживает внутриклеточное накопление жира. Для количественной оценки нужна корректированная многоэховая MRI-PDFF.','Обычная двухэховая пара не даёт надёжный процент PDFF, особенно при железе. МРТ не устанавливает метаболическую этиологию или MASH только по наличию жира.',['Сигнал печени на in-phase','Падение сигнала на opposed-phase','PDFF — отдельная количественная карта']),
f('ld-focal','Фокальный жир / сохранная паренхима','Географический участок в типичной зоне, без масс-эффекта, с проходящими сосудами и изменением сигнала на химическом сдвиге поддерживает жировое распределение.','Не всякое перивезикальное изменение — жир. Масса может содержать жир; при масс-эффекте, нетипичном усилении или рестрикции нужна оценка очага по соответствующему модулю.',['Участок жирового распределения','Сосуд проходит без смещения','Окружающая паренхима']),
f('ld-iron','Перегрузка железом','Низкий сигнал на T2/T2*, ускоренное затухание с увеличением TE, повышенный R2* поддерживают железо. Для LIC нужна валидированная калибровка с учётом поля и методики.','Не выводить mg Fe/g из визуально «тёмной печени» или произвольной формулы. Жир/шум и тяжёлая перегрузка искажают оценку; нужны качество подгонки и достаточное число ранних эхо.',['Печень с ускоренным затуханием сигнала','Многоэховая оценка T2* / R2*','LIC после валидированной калибровки']),
f('ld-cirrhosis','Цирротическая перестройка','Неровный/узловатый контур, изменение пропорций долей, расширение щелей и признаки портальной гипертензии поддерживают выраженное хроническое поражение печени.','Ранний фиброз может не менять морфологию. Сходная перестройка бывает при сосудистых нарушениях; по одной форме нельзя надёжно стадировать F1–F4 или установить причину.',['Узловатый контур','Изменённые пропорции долей','Портальная система / возможные коллатерали']),
f('ld-mre','Фиброз · роль МР-эластографии','MRE измеряет жёсткость, обычные T1/T2/динамика — морфологию и сопутствующие изменения. Укажите метод, частоту возбуждения, kPa, валидную область и ограничения.','Жёсткость повышают не только фиброз, но и воспаление, холестаз и венозный застой. Пороги УЗ-эластографии нельзя переносить на MRE; стадия зависит от валидированного протокола и этиологии.',['Валидная область измерения MRE','Зона, исключаемая из ROI: крупный сосуд/край','Карта жёсткости — условная, не реальные значения'])]
L['spread']=[
f('ld-portal','Портальная гипертензия','Портосистемные коллатерали, варикозные вены, спленомегалия и асцит поддерживают портальную гипертензию. Отмечайте пути шунтирования и проходимость портальной системы.','Диаметр воротной вены сам по себе не диагностичен. МРТ не измеряет HVPG и не заменяет клиническую оценку вариксов; отсутствие асцита не исключает значимую гипертензию.',['Портальная система','Портосистемная коллатераль','Селезёнка / спленомегалия']),
f('ld-pvt','Тромбоз воротной вены','Дефект заполнения прослеживают по воротной, селезёночной и верхней брыжеечной венам: окклюзия/неокклюзия, длина, давность по анамнезу, коллатерали/кавернома.','Медленный поток может имитировать тромб. Для опухолевого компонента ищут достоверно усиливающуюся мягкую ткань; одна рестрикция или расширение вены недостаточны.',['Дефект в воротной вене','Проходимый остаточный просвет','Коллатерали / кавернозная трансформация']),
f('ld-budd','Нарушение печёночного оттока','Для Budd–Chiari ищут прямые признаки обструкции печёночных вен/НПВ, внутрипечёночные венозные коллатерали, неоднородную перфузию и увеличение хвостатой доли.','Неоднородность печени и асцит неспецифичны. Сердечный застой, синусоидальное поражение и Budd–Chiari различают по прямым сосудистым признакам и клинике; Допплер дополняет МРТ.',['Печёночные вены с зоной обструкции','Нижняя полая вена','Изменение перфузии / венозные коллатерали']),
f('ld-congestion','Застойная гепатопатия','Расширенные НПВ/печёночные вены, рефлюкс контраста, мозаичное усиление и признаки правожелудочковой перегрузки поддерживают венозный застой.','Высокая жёсткость на фоне застоя не доказывает цирроз. Узлы при сосудистых заболеваниях оценивают отдельно; обычные правила LI-RADS нельзя механически переносить на любую сосудистую печень.',['Расширенная НПВ','Расширенные печёночные вены','Неоднородное застойное усиление'])]
L['assessment']=[['Качественно или количественно','Двухэховый chemical shift — признак жира; MRI-PDFF — корректированная доля жировых протонов; R2*=1/T2* — скорость затухания; LIC — концентрация железа по валидированной калибровке. Не взаимозаменяемы.'],['MRI-PDFF','Укажите %, метод, покрытие/ROI и качество карты. Процент PDFF не равен проценту стеатозных гепатоцитов на гистологии. По PDFF не устанавливают MASH и не присваивают гистологическую стадию фиброза.'],['Железо · LIC','mg Fe/g сухой ткани, не влажной; либо μmol Fe/g с указанным переводом. R2* указывается в s⁻¹, T2* в ms; формула R2*[s⁻¹]=1000/T2*[ms] не является формулой LIC.'],['LIC · референс ESGAR/SAR2023','<1,8 mg/g — норма; 1,8–<3,2 — пограничный диапазон; 3,2–<7,0 — лёгкая; 7,0–15,0 — умеренная; >15,0 — тяжёлая перегрузка. Это ориентиры, клинические пороги зависят от заболевания и калибровки. Не назначение хелаторов.'],['Ограничения R2*','Нужны коррекция влияния жира, шума и неоднородности поля, ранние TE и подходящая модель. На тяжёлом железе сигнал может затухнуть до первого эхо; непригодную подгонку нельзя выдавать за точное LIC.'],['MRE','kPa, метод/частота, валидный ROI, техническое качество и конфаундеры. Повышенная жёсткость не тождественна фиброзу; пороги выбирают для MRE, конкретной популяции и этиологии.'],['Морфология','Контур/доли/щели, паренхима и очаги. Нет надёжного автоматического перевода рутинной морфологии в F1–F4; ранний фиброз не исключается при обычной форме.'],['Портальная система','Проходимость, направление распространения тромба, коллатерали, селезёнка и асцит. По одной МРТ нельзя рассчитать HVPG или определить необходимость профилактики кровотечения.'],['Печёночные вены / НПВ','Обструкция и венозные коллатерали против расширения с рефлюксом при застое. При неуверенности Допплер/дальнейшая сосудистая оценка; не считать неоднородную перфузию диагнозом Budd–Chiari.'],['Очаги на изменённом фоне','Перейдите к модулю очагов печени; при сосудистой патологии, тяжёлом железе и выраженном жире типичные сигналы меняются. Для опухолевого тромба требуется убедительное усиление мягкой ткани.']]
L['pitfalls']=[['Жир + железо','Более позднее in-phase эхо может стать темнее из-за T2*, скрывая привычную картину жира. Используйте многоэховую CSE-модель с коррекцией, а не простое визуальное сравнение яркости.'],['Фокальный жир и псевдоочаг','Проверьте химический сдвиг, сосуды, масс-эффект, DWI и усиление. Географическая форма полезна, но не исключает настоящую массу.'],['Жёсткость без фиброза','Воспаление, холестаз, застой и приём пищи влияют на жёсткость. Отдельно фиксируйте ограничения/подготовку; не переносите пороги VCTE/УЗИ на MRE.'],['Тромб и артефакт потока','Проверьте несколько плоскостей и фаз, исходные серии/субтракцию, при необходимости Допплер. Дефект на одной серии или яркая DWI недостаточны для опухолевого тромба.']]
L['scan']=[['Обязательно · морфология','Вся печень/селезёнка, AX/COR T2 с/без FS, T1 IP/OP или Dixon','Доли, контуры, жир, железо, очаги; не ограничиваться одним ROI или срезом.'],['Для количественного жира','Многоэховая chemical-shift encoded MRI с картами PDFF и R2*','Валидированная коррекция T1/T2*, спектра жира, шума/артефактов; несколько сегментов без сосудов и очагов. Двухэховая пара не заменяет PDFF.'],['Для количественного железа','Валидированная R2*-релаксометрия, обычно 6–12 эхо; максимально ранний TE/малый шаг по протоколу','Метод/поле, коррекция жира/шума и качество fitting; перевод R2* в LIC только по соответствующей калибровке. Не переносить калибровку1,5T на3T.'],['По показаниям · фиброз','MRE с контролем волн/карты достоверности и валидной области','Голодание по локальному протоколу MRE, частота возбуждения и корректный ROI. При тяжёлом железе GRE-MRE может быть недиагностична; alternative SE-EPI по доступности.'],['При сосудистой / очаговой задаче','T1 FS до и динамически после контраста + DWI/ADC','Артериальная/портальная/отсроченная оценка сосудов, тромба и очагов. Контраст не нужен только для измерения PDFF/R2*/MRE.'],['Дополнительно','МР-венография / Допплер / прицельный печёночный протокол','Портальная/селезёночная/брыжеечная и печёночные вены, НПВ; гепатобилиарная фаза для очагов по задаче. Недиагностические измерения явно обозначать.']]
L['checks']=['Морфология печени, очаги и сравнительные исследования','Жир: качественный признак или валидная PDFF в %','Железо: поле, T2*/R2*, LIC, единицы и калибровка','MRE: качество, метод, kPa и конфаундеры','Портальная/селезёночная/брыжеечная вены, тромб и коллатерали','Печёночные вены/НПВ, обструкция или застой','Селезёнка/асцит, клиническая причина и ограничения']
L['reports']=[['Качественный стеатоз','Диффузное снижение сигнала печени на opposed-phase относительно in-phase соответствует накоплению внутриклеточного жира. Количественная MRI-PDFF не выполнялась; процент стеатоза не определён. Этиология и наличие MASH по МРТ не установлены.'],['PDFF','Выполнена [метод] MRI-PDFF с коррекцией [ ]. Среднее/медианное значение по [покрытие/ROI] [ ]%, диапазон [ ]. Качество [ ]. PDFF отражает долю жировых протонов и не равна проценту поражённых гепатоцитов на гистологии.'],['Перегрузка железом','Выявлено ускоренное затухание сигнала печени: T2* [ ] ms / R2* [ ] s⁻¹ на [1,5/3T], метод [ ]. LIC по валидированной калибровке [ ] mg Fe/g сухой ткани. Качество fitting [ ]. При отсутствии валидной количественной серии LIC не рассчитывается.'],['Хроническая перестройка','Изменены пропорции долей, [неровный/узловатый] контур печени. Коллатерали [ ], селезёнка [ ], асцит [ ]. Картина соответствует выраженному хроническому поражению печени в клиническом контексте. Точная стадия фиброза по рутинной морфологии не установлена.'],['Портальный тромбоз','Дефект заполнения [сегмент, длина], просвет [неокклюзирован/окклюзирован], распространение на [ ], коллатерали [ ]. Достоверное усиление внутрипросветной ткани [есть/нет/неоценимо]. Опухолевый компонент [подозревается/не подтверждён/не может быть оценён].'],['Отток / MRE','Печёночные вены и НПВ [ ], признаки [обструкции/застоя] [ ]. MRE [метод, частота]: жёсткость [ ] kPa, валидная область/качество [ ], ограничения [ ]. Повышение жёсткости интерпретируется с учётом воспаления, холестаза и застоя.']]
D=dict(title='Образования надпочечников',localLabel='Типы образований',spreadLabel='CSI · рост · двусторонность')
D['local']=[
f('ad-adenoma','Аденома · внутриклеточный жир','Однородное образование с убедительным падением сигнала на opposed-phase относительно in-phase поддерживает богатую внутриклеточным липидом аденому при соответствующей клинической картине.','Жиробедная аденома может не терять сигнал. Падение сигнала не гарантирует доброкачественность любой массы; некроз, кровоизлияние, онкоанамнез и неоднородность требуют отдельной оценки.',['Однородная масса надпочечника','Почка — орган происхождения нужно отличать','Сопоставленная пара IP/OP']),
f('ad-myelo','Миелолипома · макроскопический жир','Узел надпочечникового происхождения с макроскопическим жиром: T1-яркий компонент подавляется на fat-sat / подтверждается Dixon fat-only. Возможна смесь жира и кроветворной ткани.','Не путать макроскопический жир с внутриклеточным липидом аденомы. Определите орган происхождения; крупная атипичная жировая забрюшинная масса может быть другой опухолью.',['Макроскопический жир','Мягкотканный компонент','Верхний полюс почки / зона надпочечника']),
f('ad-bleed','Кровоизлияние','Сигнал зависит от стадии; подострая кровь часто T1-яркая и не подавляется как жир. Ищите истинное усиление на корректно совмещённой субтракции, анамнез и изменение размеров.','Кровоизлияние может скрывать опухоль, включая феохромоцитому. Отсутствие явного узла на одном исследовании не доказывает первичную гематому; требуется контекст и динамика.',['Геморрагическое содержимое','Стенка / возможный скрытый усиливающийся узел','Окружающие изменения']),
f('ad-pheo','Феохромоцитома','Обычно усиливающаяся масса без типичного равномерного CSI-падения; T2-сигнал вариабелен, возможны некроз и кровь. По МРТ можно предположить, но не подтвердить гормонально активную опухоль.','«Яркая лампочка» на T2 бывает не всегда и неспецифична. Не рекомендовать пункцию до биохимического исключения феохромоцитомы.',['Усиливающаяся ткань','Некротический/геморрагический компонент','Проверьте местное распространение']),
f('ad-suspicious','Подозрительная первичная опухоль','Неоднородная крупная масса, инвазия, венозное распространение, некроз и рост повышают подозрение. Оцените соседние органы, почечную вену/НПВ, узлы и отдалённые очаги в покрытии.','Размер ≥4 см сам по себе не устанавливает адренокортикальный рак. Неоднородную массу нельзя «обезвредить» CSI-падением в одном жировом фрагменте или расчётом washout.',['Неоднородная масса','Подозрение на распространение за капсулу','Венозный компонент — проверять усиление']),
f('ad-metastasis','Метастазы / лимфома','Онкологический анамнез, двусторонность, рост и другие очаги повышают вероятность вторичного поражения. Отсутствие CSI-падения делает липидную аденому менее вероятной, но не доказывает метастаз.','У онкопациента могут быть аденома и феохромоцитома. ПЭТ/КТ или биопсию выбирают, только если результат изменит тактику; биохимические условия остаются обязательны.',['Образование надпочечника','Противоположный надпочечник оценивают независимо','Другие опухолевые очаги / контекст'])]
D['spread']=[
f('ad-csi','Chemical shift: правильная проверка','Сравните одинаковые ROI/геометрию на IP и OP, убедитесь в корректных TE для поля, исключите примесь перинадпочечникового жира и движение. Падение должно оценивать саму массу, а не её чёрную границу.','India-ink по контуру — артефакт границы жир/вода, не доказательство липида внутри опухоли. Количественные индексы CSI зависят от техники; универсального автопорога здесь нет.',['Масса на in-phase','Та же масса на opposed-phase','Контроль совмещения / одинаковый ROI']),
f('ad-growth','Динамика · >20% И ≥5 мм','Для неопределённой массы без операции после исходной оценки ESE2023 предлагает контроль бесконтрастной КТ или МРТ через 6–12 мес. Значимый рост: >20% максимального диаметра И одновременно ≥5 мм.','Измеряйте сопоставимо, с датами и плоскостью. Ровно20% не соответствует условию >20%; относительный рост без5 мм тоже недостаточен. Рост ведёт к профильной переоценке, не к автоматической операции приложения.',['Исходный контур — пунктир','Текущий максимальный диаметр','Та же масса / сопоставимая плоскость']),
f('ad-bilateral','Двусторонние изменения','Каждую сторону характеризуют отдельно. Различают гиперплазию, двусторонние аденомы, одинаковые неаденомные и разные по морфологии образования. Сопоставьте клинику и гормональные данные.','При двусторонних кровоизлияниях, крупных метастазах, лимфоме/инфильтрации нужна оценка надпочечниковой недостаточности. Двусторонность не означает метастазы автоматически.',['Правый надпочечник пациента','Левый надпочечник пациента','Морфология каждой массы и внеадреналовый контекст'])]
D['assessment']=[['Сначала происхождение','Подтвердите надпочечниковое, а не почечное/панкреатическое/забрюшинное происхождение. Размеры, однородность, жир/кровь, усиление, инвазия и сравнение. МРТ не определяет гормональную активность.'],['ESE2023 · роль КТ','Первичная характеризация обычно бесконтрастной КТ. Однородная масса ≤10 HU — доброкачественный критерий независимо от размера. HU — единицы КТ; на МРТ этот порог неприменим.'],['МРТ · CSI','Убедительное равномерное падение OP-сигнала в однородной массе поддерживает липидную аденому. Неоднородную массу нельзя классифицировать как безопасную по одному ROI. При неясной МРТ — профильное уточнение, не диагноз метастаза.'],['КТ 11–20 HU и <4 см','При однородной массе и отсутствии значимого гормонального избытка ESE2023 предлагает дополнительную характеризацию сразу; альтернативно контроль через12 мес. Не переносить КТ-алгоритм на некорректно измеренные МР-сигналы.'],['≥4 см И (неоднородность ИЛИ >20 HU)','Высокая настороженность по ESE2023: профильная команда/стадирование, часто обсуждение хирургии. Обе части условия важны; ≥4 см без этих признаков — другая ситуация. >20 HU относится к бесконтрастной КТ.'],['Другие неопределённые массы','Например ≥4 см с11–20 HU, <4 см с>20 HU или <4 см с неоднородностью: индивидуальная оценка/дополнительная визуализация. При отсутствии операции и сохраняющейся неопределённости — контроль6–12 мес по маршруту.'],['Рост · ESE2023','>20% максимального диаметра И ≥5 мм абсолютного прироста за6–12 мес. При меньшем приросте может потребоваться ещё один контроль6–12 мес. Даты, плоскость и погрешность измерения обязательны.'],['Эндокринная оценка','Гормональную функцию оценивает эндокринолог. Метанефрины при признаках, нетипичных для доброкачественной аденомы; при АГ/необъяснимой гипокалиемии — альдостерон/ренин. Условия оценки кортизола — по клиническому протоколу.'],['Биопсия · все3 условия','Только если гормонально неактивна (особенно исключена феохромоцитома), по визуализации не доказана доброкачественность И гистология изменит тактику. Не рутинный метод типирования первичной опухоли; ESE2023 обычно рассматривает её при внеадреналовом онкоанамнезе.'],['Возраст / беременность','У беременных и пациентов <40 лет неопределённая масса требует ускоренной профильной оценки. Для прицельного исследования у беременных/детей предпочтительна МРТ; необходимость контраста решается отдельно.']]
D['pitfalls']=[['Washout не переносится на МРТ','КТ-порогам вымывания нет прямого аналога по произвольной МР-динамике. Неоднородную/некротическую массу нельзя считать аденомой по вымыванию отдельного фрагмента.'],['Онкологический анамнез','RCC и некоторые другие метастазы могут содержать липид или пересекаться по сигналу с аденомой. Сопоставьте предыдущие исследования, однородность и общее распространение; CSI не отменяет контекст.'],['Кровь маскирует ткань','T1-яркость до контраста требует субтракции с проверкой регистрации. Важны остаточный усиливающийся узел, инвазия, динамика рассасывания и клиническая причина кровоизлияния.'],['МРТ и гормоны','Гладкая небольшая масса может быть функционально активной. При подозрении на феохромоцитому недопустима рекомендация диагностической пункции без её биохимического исключения.']]
